package com.andye.warmod.icbm.client.render;
import com.mojang.blaze3d.vertex.PoseStack;import com.mojang.blaze3d.vertex.VertexConsumer;import net.minecraft.util.Mth;
public final class IcbmExhaustRenderer {private IcbmExhaustRenderer(){}public static void render(final PoseStack.Pose p,final VertexConsumer b,final long seed,final double elapsed,final IcbmLongRangeRenderContext.Lod lod){double flicker=.9+.1*Math.sin(elapsed*2.1+(seed&255));plume(p,b,-2.58F,.34F,(float)(3.5*flicker),255,250,190,235);if(lod==IcbmLongRangeRenderContext.Lod.EXTREME)return;plume(p,b,-2.62F,.72F,(float)(7*flicker),255,152,40,175);if(lod!=IcbmLongRangeRenderContext.Lod.FAR)plume(p,b,-2.68F,1.25F,(float)(11*flicker),205,205,190,90);}private static void plume(final PoseStack.Pose p,final VertexConsumer b,final float top,final float radius,final float length,final int r,final int g,final int bl,final int a){for(int q=0;q<2;q++){float angle=q*Mth.HALF_PI,c=Mth.cos(angle),s=Mth.sin(angle);v(p,b,-c*radius,top,-s*radius,0,0,r,g,bl,a);v(p,b,c*radius,top,s*radius,1,0,r,g,bl,a);v(p,b,c*.05F,top-length,s*.05F,1,1,r,g,bl,0);v(p,b,-c*.05F,top-length,-s*.05F,0,1,r,g,bl,0);}}private static void v(final PoseStack.Pose p,final VertexConsumer b,final float x,final float y,final float z,final float u,final float vv,final int r,final int g,final int bl,final int a){b.addVertex(p,x,y,z).setColor(r,g,bl,a).setUv(u,vv).setOverlay(0).setLight(0xF000F0).setNormal(p,0,1,0);}}